def _fix_warehouse_remaining_quantities(apps, schema_editor):
    """Recompute remaining_quantity so it equals (entered - released), matching
    the flow/inventory/dashboard views. Legacy rows seeded remaining with the
    agreed quantity at creation, which made remaining disagree with stored-released."""
    WarehouseStorageItem = apps.get_model("inventory", "WarehouseStorageItem")
    for si in WarehouseStorageItem.objects.all():
        entered = sum(
            ei.quantity
            for ei in si.entry_items.all()
        )
        released = sum(
            ri.quantity
            for ri in si.release_items.all()
        )
        si.remaining_quantity = max(entered - released, 0)
        si.save(update_fields=["remaining_quantity"])


